const TOKEN = '__CC_CALENDAR_FACADE_TOKEN__';
const item = $input.first().json;
const hdr = item.headers || {};
const supplied = hdr['x-cc-token'];
if (supplied !== TOKEN) { throw new Error('cc-calendar-facade - unauthorized'); }
const body = item.body || {};
if (!body || !body.mode) { throw new Error('cc-calendar-facade - missing mode'); }
// Mode allowlist, never `!== ''`. The credential behind the lib is full-scope, so
// this check is the boundary, not the OAuth scope. The three write modes are
// reachable ONLY from Central Command's Executor, i.e. only after the operator
// approved the proposal that named them. Adding a mode here widens that surface.
const MODES = ['list', 'create_event', 'update_event', 'delete_event'];
if (!MODES.includes(body.mode)) { throw new Error('cc-calendar-facade - unsupported mode'); }
return [{ json: body }];
